// ============================================================
// AGENT #2 — COMPETITIVE INTELLIGENCE
// So sánh Hecatech vs đối thủ: GMV, creative, giá, affiliate
// Chạy mỗi thứ Hai, gửi briefing cho CEO + Leaders
// ============================================================

// Chỉ chạy vào thứ Hai — bỏ qua các ngày khác
const isMonday = new Date().getDay() === 1;
if (!isMonday) {
  return [{ json: { skipped: true, reason: 'Competitive Intel chỉ chạy thứ Hai' } }];
}

const competitorRows = $('Read Competitor Data Sheet').all().map(i => i.json);
const hecatechRows   = $('Read Hecatech MTD Data').all();
let kalodata = {};
try { kalodata = $('Fetch Kalodata via HTTP').first()?.json || {}; } catch(e) {}

const today = new Date();
const weekStr = `Tuần ${Math.ceil(today.getDate()/7)} - Tháng ${today.getMonth()+1}/${today.getFullYear()}`;

// Extract Hecatech MTD metrics
const col = (item, idx) => { const obj = item.json||item; return Object.values(obj)[idx]; };
const fmt = (n) => {
  n = parseFloat(n) || 0;
  if (Math.abs(n)>=1e9) return (n/1e9).toFixed(2)+' tỷ';
  if (Math.abs(n)>=1e6) return Math.round(n/1e6)+' tr';
  return n.toLocaleString('vi-VN');
};

const hecatechMetrics = {};
hecatechRows.forEach(item => {
  const name = (col(item,0)||'').toString().trim();
  if (name) hecatechMetrics[name] = parseFloat(col(item,5)) || 0;
});

// Organize competitor data by brand
const competitors = {};
competitorRows.forEach(r => {
  const brand = r['Brand'] || r['brand'] || 'Unknown';
  if (!competitors[brand]) competitors[brand] = [];
  competitors[brand].push(r);
});

// Build comparison data for Claude
const comparisonData = {
  week: weekStr,
  hecatech: {
    gmv_mtd:    fmt(hecatechMetrics['Tổng GMV'] || 0),
    revenue_mtd: fmt(hecatechMetrics['★ LỢI NHUẬN RÒNG'] || 0),
    take_rate:   ((hecatechMetrics['Ads/DS (Take Rate)'] || 0)*100).toFixed(1)+'%'
  },
  competitors: Object.entries(competitors).map(([brand, data]) => ({
    brand,
    latestData: data[data.length - 1] || {}
  })),
  kalodata_top: Array.isArray(kalodata.data) ? kalodata.data.slice(0,5) : []
};

const systemPrompt = `Bạn là chuyên gia phân tích cạnh tranh cho Hecatech — công ty TikTok commerce mỹ phẩm VN.
Nhiệm vụ: Tạo Competitive Intelligence Briefing tuần này.
Focus: Beucare và Retolab là 2 brand chính của Hecatech. Đối thủ cạnh tranh chính trong ngành beauty TikTok VN.
Viết tiếng Việt, súc tích, tập trung insight có thể hành động được.`;

const userPrompt = `COMPETITIVE INTELLIGENCE BRIEFING — ${weekStr}

Data:
${JSON.stringify(comparisonData, null, 2)}

Tạo báo cáo theo format:

🔍 COMPETITIVE BRIEF — ${weekStr}

📊 VỊ THẾ HECATECH TUẦN NÀY
• GMV MTD: [số] vs đối thủ hàng đầu: [tên] [số]
• Xu hướng: [tăng/giảm/ổn định]

🔥 ĐỘNG THÁI ĐỐI THỦ ĐÁNG CHÚ Ý
[Top 3 insight quan trọng nhất về đối thủ]

📱 CREATIVE TREND TUẦN NÀY
[2-3 xu hướng creative/hook đang winning trên TikTok beauty]

💡 KHUYẾN NGHỊ CHO HECATECH
1. [Hành động cụ thể để tận dụng cơ hội]
2. [Hành động phòng thủ trước mối đe dọa]
3. [Experiment cần test ngay tuần này]

⚠️ RỦI RO CẦN THEO DÕI
[1-2 điểm rủi ro từ thị trường/đối thủ]

Dưới 400 từ.`;

return [{
  json: {
    comparisonData,
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 1200,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];

const briefingText = $input.first().json?.content?.[0]?.text || '⚠️ Lỗi tạo báo cáo.';
const msg = { msg_type: 'text', content: { text: briefingText } };
// Send to both CEO and Leaders group
return [
  { json: { url: $vars.LARK_CEO_WEBHOOK_URL,     larkMessage: msg } },
  { json: { url: $vars.LARK_LEADERS_WEBHOOK_URL, larkMessage: msg } }
];
